sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    if (api.data.delete_entity_types.output && api.data.delete_entity_types.output["deactivated-retired"]) {
        const items = [];
        let associatedItems = api.data.delete_entity_types.output["deactivated-retired"];
        let keys = Object.keys(associatedItems);
        var workspaceURL = api.data.delete_entity_types.output["pageURL"];

        for (let i = 0; i < keys.length; i++) {
            var link = associatedItems[keys[i]].link;
            var title = associatedItems[keys[i]].label;
            var url = link;
            if(link.includes("sysparm_query=")){
                var query = link.substr(link.indexOf('sysparm_query=') + 'sysparm_query='.length);
                url = `/now/${workspaceURL}/list-view/${keys[i]}/params/listTitle/${title}/query/${query}`; 
            }

            var item = {
                label: associatedItems[keys[i]].label,
                value: {
                    type: 'text-link',
                    label: associatedItems[keys[i]].number,
                    href: url,
                    underlined: true,
                    opensWindow: true
                }
            };
            items.push(item);
        }
        return items;
    }
}
